// AIAction defines model for AIAction.
type AIAction struct {
	// CacheUnchangedSteps If enabled, will load cached results from the previous preview job for unchanged jobs. Disable this if you're developing your own custom AI Labeling job, and want to always re-run all steps.
	CacheUnchangedSteps bool            `json:"cacheUnchangedSteps"`
	Config              AIActionsConfig `json:"config"`

	// DisplayName Name to show to the user when interacting with this action (e.g. in a table, or when running the action). Will return either "name" (if present), or a name derived from the transformation block.
	DisplayName string `json:"displayName"`

	// GridColumnCount Number of grid columns to use during preview.
	GridColumnCount int `json:"gridColumnCount"`
	Id              int `json:"id"`

	// LastPreviewState Contains the last preview state, this is filled with whatever was ran last, so when you refresh an AI Action it'll always have the exact same state as before refresh.
	LastPreviewState *struct {
		ProposedChanges []struct {
			ProposedChanges SampleProposedChanges `json:"proposedChanges"`
			SampleId        int                   `json:"sampleId"`
			Step            int                   `json:"step"`
		} `json:"proposedChanges"`
		Samples []Sample `json:"samples"`
	} `json:"lastPreviewState,omitempty"`

	// MaxDataPreviewCount When rendering preview items, the max amount of items to show (pass this into the previewAIActionsSamples)
	MaxDataPreviewCount int `json:"maxDataPreviewCount"`

	// Name Manually set name (optional)
	Name          *string         `json:"name,omitempty"`
	PreviewConfig AIActionsConfig `json:"previewConfig"`

	// SetMetadataAfterRunning After the action runs, add this key/value pair as metadata on the affected samples.
	SetMetadataAfterRunning []struct {
		Key   string `json:"key"`
		Value string `json:"value"`
	} `json:"setMetadataAfterRunning"`
}

// AIActionsConfig defines model for AIActionsConfig.
type AIActionsConfig struct {
	DataCategory AIActionsDataCategory `json:"dataCategory"`

	// DataMetadataKey Metadata key to filter on. Required if dataCategory is equal to "dataWithoutMetadataKey" or "dataWithMetadata".
	DataMetadataKey *string `json:"dataMetadataKey,omitempty"`

	// DataMetadataValue Metadata value to filter on. Required if dataCategory is equal to "dataWithMetadata".
	DataMetadataValue *string               `json:"dataMetadataValue,omitempty"`
	Steps             []AIActionsConfigStep `json:"steps"`
}

// AIActionsConfigStep defines model for AIActionsConfigStep.
type AIActionsConfigStep struct {
	// Parameters Parameters for the transformation block. These map back to the parameters in OrganizationTransformationBlock 'parameters' property.
	Parameters map[string]string `json:"parameters"`

	// TransformationBlockId The selected transformation block ID.
	TransformationBlockId int `json:"transformationBlockId"`
}

